import { KEYS, headObject, putObject } from "../store.mjs";
import { ensureCollectionMeta, now, CONTENT_META } from "../meta.mjs";
import { missingContentType } from "../problems.mjs";

// Stores a Resource's content. The content object carries the stamps the
// Resource Metadata derives (creation time and author, key epoch, writer
// label); an absent Key-Epoch or Writer-Id header clears the prior stamp,
// per the spec's declare-or-clear rule.
export async function writeResourceContent(req, { spaceId, collectionId, resourceId, invoker, preconditions: given }) {
  if (req.body === null || !req.contentType) {
    throw missingContentType();
  }
  const key = KEYS.resource(collectionId, resourceId);
  const current = await headObject(spaceId, key);
  const stamped = current?.metadata ?? {};
  const metadata = {
    [CONTENT_META.createdAt]: stamped[CONTENT_META.createdAt] ?? now(),
    ...((stamped[CONTENT_META.createdBy] ?? invoker) && {
      [CONTENT_META.createdBy]: stamped[CONTENT_META.createdBy] ?? invoker,
    }),
    ...(req.headers["key-epoch"] && { [CONTENT_META.epoch]: req.headers["key-epoch"] }),
    ...(req.headers["writer-id"] && { [CONTENT_META.writerId]: req.headers["writer-id"] }),
  };
  const { etag } = await putObject(spaceId, key, {
    body: req.body,
    contentType: req.contentType,
    metadata,
    ...given,
  });
  if (current === null) {
    await ensureCollectionMeta(spaceId, collectionId, invoker);
  }
  return { etag, created: current === null };
}

